function fixedUnit(category:string,key:string){const units:Record<string,string>={'杆子|厚度/重量':'mm','杆子|长度':'mm','手喷|尺寸大小':'mm','顶喷|尺寸大小':'mm','电话线|长度':'m','手喷软管|长度':'m','中叉+墙座|适配杆径':'mm'};return units[`${category}|${key}`]||''}
function numericOnly(value:unknown){return String(value??'').replace(',', '.').replace(/(毫米|mm|米|m)\s*$/i,'').replace(/[^\d.×xX*／/\\-]/g,'').replace(/[xX*]/g,'×')}
function normalizeAttribute(category:string,key:string,value:unknown){const unit=fixedUnit(category,key);return unit?numericOnly(value):String(value??'')}
function normalizeAttributes(category:string,attributes:Record<string,string>={}){return Object.fromEntries(Object.entries(attributes).map(([key,value])=>[key,normalizeAttribute(category,key,value)]))}
function formatAttribute(category:string,key:string,value:unknown){const normalized=normalizeAttribute(category,key,value),unit=fixedUnit(category,key);return unit&&normalized?`${normalized}${unit}`:normalized}
function money(value:unknown){const amount=Number(value);return `${Number.isFinite(amount)?amount.toFixed(2):'0.00'} 元`}
