async function clearLogs(){if(!await askConfirm('清除后，当前日志将无法恢复。确定清除全部日志吗？','清除操作日志'))return;try{await api('/api/admin/audit-logs',{method:'DELETE'});selectedLog.value=null;notice.value='操作日志已清除';await loadAdmin()}catch(e:any){showAlert(e.message)}}
