async function setBodyActive(x:Body,active:boolean){if(x.active===active)return;try{await api('/api/admin/bodies/'+x.id,{method:'PATCH',body:JSON.stringify({name:x.name,model:x.model,image_url:x.image_url||'',description:x.description||'',cost:Number(x.cost||0),active})});notice.value=active?'主体已启用':'主体已停用';await loadAdmin()}catch(e:any){notice.value=e.message;showAlert(e.message)}} async function deleteQuote(x:any){if(!await askConfirm('确定删除这张报价单吗？删除后不可恢复。','删除报价单'))return;try{await api('/api/admin/quotes/'+x.quote_no,{method:'DELETE'});notice.value='报价单已删除';await loadAdmin()}catch(e:any){notice.value=e.message;showAlert(e.message)}} function setAccessoryAttribute(k:string,v:string){accessoryForm.attributes[k]=normalizeAttribute(accessoryForm.category,k,v)} async function saveAccessory(){try{await api(accessoryForm.id?`/api/admin/accessories/${accessoryForm.id}`:'/api/admin/accessories',{method:accessoryForm.id?'PATCH':'POST',body:JSON.stringify({...accessoryForm,attributes:normalizeAttributes(accessoryForm.category,accessoryForm.attributes),cost:Number(accessoryForm.cost),default_qty:Number(accessoryForm.default_qty),min_qty:Number(accessoryForm.min_qty),max_qty:Number(accessoryForm.max_qty)})});originalAccessoryImageUrl.value=accessoryForm.image_url;notice.value='配件已保存';clearForms();await loadAdmin()}catch(e:any){notice.value=e.message;showAlert(e.message)}} function accessoryPayload(x:Accessory,active=x.active??true){return {name:x.name,model:x.model,category:x.category,image_url:x.image_url||'',attributes:normalizeAttributes(x.category,x.attributes||{}),cost:Number(x.cost||0),default_qty:Number(x.default_qty||0),min_qty:Number(x.min_qty||0),max_qty:Number(x.max_qty||0),active}} async function setAccessoryActive(x:Accessory,active:boolean){if(x.active===active)return;try{await api(`/api/admin/accessories/${x.id}`,{method:'PATCH',body:JSON.stringify(accessoryPayload(x,active))});notice.value=active?'配件已启用':'配件已停用';await loadAdmin()}catch(e:any){notice.value=e.message;showAlert(e.message)}} async function deleteAccessory(x:Accessory){if(!await askConfirm('确定删除这条配件吗？删除后不可恢复，关联兼容规则也会一并删除。','删除配件'))return;try{await api(`/api/admin/accessories/${x.id}`,{method:'DELETE'});notice.value='配件已真实删除';await loadAdmin()}catch(e:any){notice.value=e.message;showAlert(e.message)}}
async function saveUser(){if(!userForm.id&&userForm.password.length<8){notice.value='新增账号的密码至少需要 8 位';return}if(userForm.password&&userForm.password.length<8){notice.value='密码至少需要 8 位';return}const p:any={username:userForm.username,role:userForm.role,active:userForm.active};if(!userForm.id||userForm.password)p.password=userForm.password;try{await api(userForm.id?`/api/admin/users/${userForm.id}`:'/api/admin/users',{method:userForm.id?'PATCH':'POST',body:JSON.stringify(p)});notice.value='账号已保存';clearForms();await loadAdmin()}catch(e:any){showAlert(e.message)}}
async function setUserActive(x:any,active:boolean){if(x.active===active||x.username===session.value?.username&&!active)return;try{await api('/api/admin/users/'+x.id,{method:'PATCH',body:JSON.stringify({username:x.username,role:x.role,active})});notice.value=active?'账号已启用':'账号已停用';await loadAdmin()}catch(e:any){notice.value=e.message;showAlert(e.message)}}
async function saveRule(){try{await api('/api/admin/compatibility-rules',{method:'POST',body:JSON.stringify(ruleForm)});Object.assign(ruleForm,{source_accessory_id:0,target_accessory_id:0});notice.value='规则已保存';await loadAdmin()}catch(e:any){showAlert(e.message)}} async function setRuleActive(rule:any,active:boolean){if(rule.active===active)return;try{await api('/api/admin/compatibility-rules/'+rule.id,{method:'PATCH',body:JSON.stringify({...rule,active})});notice.value=active?'规则已启用':'规则已停用';await loadAdmin()}catch(e:any){showAlert(e.message)}} async function deleteRule(rule:any){const ok=await askConfirm('删除后，这条兼容规则将不再参与组合校验。确定删除吗？','删除兼容规则');if(!ok)return;try{await api('/api/admin/compatibility-rules/'+rule.id,{method:'DELETE'});notice.value='规则已删除';await loadAdmin()}catch(e:any){showAlert(e.message)}} async function uploadImage(e:Event,target:'body'|'accessory'){const input=e.target as HTMLInputElement;const f=input.files?.[0];if(!f)return;try{const form=new FormData();form.append('file',f);const r=await api('/api/admin/uploads',{method:'POST',body:form});if(target==='body'){const previous=bodyForm.image_url;bodyForm.image_url=r.url;releasePendingImage(previous,originalBodyImageUrl.value)}else{const previous=accessoryForm.image_url;accessoryForm.image_url=r.url;releasePendingImage(previous,originalAccessoryImageUrl.value)}const container=input.closest('label')||input.parentElement;let previewImg=container?.querySelector('img.upload-preview') as HTMLImageElement|null;if(!previewImg){previewImg=document.createElement('img');previewImg.className='upload-preview';container?.appendChild(previewImg)}previewImg.src=r.url;notice.value='图片上传成功，可预览并保存'}catch(err:any){notice.value=err.message;showAlert(err.message)}}
async function softDelete(type:'body'|'accessory'|'user',id:number){const userDelete=type==='user';const message=userDelete?'确定停用这条账号吗？历史报价和日志需要保留账号归属。':'确定永久删除这条主体吗？关联历史报价只保留快照，图片也会一并清理。';if(!await askConfirm(message,userDelete?'停用账号':'永久删除主体'))return;try{await api(`/api/admin/${type==='body'?'bodies':type==='accessory'?'accessories':'users'}/${id}`,{method:'DELETE'});notice.value=userDelete?'账号已停用，历史数据保留':'主体已真实删除';await loadAdmin()}catch(e:any){notice.value=e.message;showAlert(e.message)}} async function openAdminQuote(no:string){adminQuoteDetail.value=await api(`/api/admin/quotes/${no}`)} async function voidQuote(no:string){await api(`/api/admin/quotes/${no}/void`,{method:'POST'});notice.value='报价已作废';await loadAdmin()}
const logActionLabels:Record<string,string>={create:'新增',update:'修改',delete:'删除',void:'作废',upload:'上传',test:'试算',login:'登录',logout:'退出'}
const logTargetLabels:Record<string,string>={user:'账号',settings:'计价参数',body:'主体',accessory:'配件',compatibility_rule:'兼容规则',quote:'报价单',image:'图片',pricing:'计价试算',session:'会话'}
const logFieldLabels:Record<string,string>={username:'账号',role:'角色',active:'状态',name:'名称',model:'型号',category:'类别',cost:'成本',image_url:'图片地址',description:'描述',attributes:'参数',default_qty:'默认数量',min_qty:'最小数量',max_qty:'最大数量',multiplier:'统一倍率',labor_fee:'统一人工费',tax_rate_percent:'税率',freight:'运费',quote_valid_days:'有效期',max_discount_percent:'最大折扣',minimum_price:'最低售价',rule_type:'规则类型',source_accessory_id:'源配件编号',target_accessory_id:'目标配件编号',final_price:'最终售价',line_count:'配件行数',discount_type:'折扣类型',filename:'文件名',content_type:'文件类型',size:'文件大小'}
function formatLogAction(action:string){return logActionLabels[action]||action}
function formatLogTarget(target:string){return logTargetLabels[target]||target}
function formatLogValue(key:string,value:any){if(key==='active')return value?'启用':'停用';if(key==='role')return value==='admin'?'管理员':'员工';if(key==='rule_type')return value==='excludes'?'互斥':'依赖';if(key==='discount_type')return value==='percent'?'百分比折扣':'固定金额折扣';if(value&&typeof value==='object')return JSON.stringify(value);return String(value)}
function formatLogDetail(detail:any){if(!detail||typeof detail!=='object')return String(detail||'暂无详情');return Object.entries(detail).map(([key,value])=>`${logFieldLabels[key]||key}：${formatLogValue(key,value)}`).join(' · ')} function logDetailEntries(detail:any){if(!detail||typeof detail!=='object')return [{key:'详情',value:String(detail||'暂无详情')}];return Object.entries(detail).map(([key,value])=>({key:logFieldLabels[key]||key,value:formatLogValue(key,value)}))} function logTargetRef(x:any){if(!x.target_id)return '';return x.target_type==='quote'?x.target_id:`编号 ${x.target_id}`} function date(v:string){return new Date(v).toLocaleDateString('zh-CN')} function dateTime(v:string){return new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})} function statusText(v:string){return ({saved:'已保存',active:'生效中',expired:'已过期',void:'已作废'} as Record<string,string>)[v]||v}
onMounted(async()=>{try{session.value=await api('/api/auth/me');await loadCatalog();if(session.value.role==='admin'){await loadAdmin();await nextTick(updateQuoteChart)}}catch{}})
</script>

<template>
<main class="app-shell">
<div v-if="dialog.open" class="app-dialog-backdrop" @click.self="resolveDialog(false)"><div class="app-dialog" role="dialog" aria-modal="true" :aria-label="dialog.title"><div class="app-dialog-icon" :class="dialog.kind==='alert'?'is-alert':'is-confirm'">{{dialog.kind==='alert'?'!':'?'}}</div><div class="app-dialog-copy"><p class="eyebrow">{{dialog.kind==='alert'?'NOTICE':'CONFIRM ACTION'}}</p><h3>{{dialog.title}}</h3><p>{{dialog.message}}</p></div><div class="app-dialog-actions"><button v-if="dialog.kind==='confirm'" type="button" class="pill-button" @click="resolveDialog(false)">取消</button><button type="button" class="primary" @click="resolveDialog(true)">{{dialog.kind==='confirm'?'确定':'知道了'}}</button></div></div></div>
<section v-if="!session" class="login-layout"><div class="login-art"><div class="constellation"><span v-for="n in 7" :key="n" :style="{'--i':n}"></span></div><p class="eyebrow">SHOWER / PRICING STUDIO</p><h1>让每一套<br><em>花洒组合</em>都有清晰答案。</h1><p class="intro">内部报价工作台。先选择主体，再搭配配件，服务器统一核算最终售价。</p><div class="login-note"><span>✦</span><div><b>组件星轨</b><small>把每个组件连接到一张可追溯报价单</small></div></div></div><form class="login-card" autocomplete="off" @submit.prevent="login"><div class="brand-mark">✦ <span>星瀑</span></div><p class="eyebrow">INTERNAL PRICING</p><h2>欢迎回来</h2><p class="muted">登录你的工作台</p><label>账号<input v-model="loginForm.username" autocomplete="off"></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="new-password"></label><button class="primary wide">进入工作台 <span>→</span></button><p v-if="loginError" class="error">{{loginError}}</p></form></section>
<section v-else class="workspace"><header class="topbar"><div class="brand-mark">✦ <span>星瀑计价平台</span></div><div class="topbar-right"><span class="role-chip">{{session.role==='admin'?'管理员':'员工'}}</span><span class="username">{{session.username}}</span><button class="ghost" @click="logout">退出</button></div></header>
<section v-if="session.role==='employee'" class="employee-shell"><div class="employee-intro"><div><p class="eyebrow">CONFIGURATION WORKBENCH</p><h1>从一个主体，搭出一整套花洒。</h1><p>按步骤选择组件和数量，最后保存一张有有效期的套装报价。</p></div><div class="progress-copy"><b>0{{employeeStep}} / 03</b><span>{{employeeStep===1?'选择主体':employeeStep===2?'搭配配件':'确认报价'}}</span></div></div><div class="stepper-dock"><div class="stepper-dock-inner"><span class="stepper-caption">配置进度</span><div class="stepper"><button v-for="(s,i) in ['选择主体','搭配配件','确认套装']" :key="s" :class="{active:employeeStep===i+1,done:employeeStep>i+1}" @click="goToStep(i+1)"><span>{{employeeStep>i+1?'✓':i+1}}</span>{{s}}</button></div><b class="stepper-current">{{employeeStep}} / 3 · {{employeeStep===1?'选择主体':employeeStep===2?'搭配配件':'确认套装'}}</b></div></div><div class="employee-grid"><section class="workbench-card">
<div v-if="employeeStep===1" class="step-panel"><div class="panel-heading"><div><p class="eyebrow">STEP 01 · BASE</p><h2>先选择一个花洒主体</h2><p>一张报价单只能对应一个主体，后续配件都会围绕它组合。</p></div><span class="counter">{{visibleBodies.length}} / {{bodies.length}} 款</span></div><div class="body-toolbar"><label class="quick-filter"><span>⌕</span><input v-model="bodyQuery" placeholder="筛选花洒名称、型号或描述"><button v-if="bodyQuery" type="button" aria-label="清除花洒筛选" @click="bodyQuery=''">×</button></label><span class="result-count">{{visibleBodies.length}} 个结果</span></div><div v-if="visibleBodies.length" class="body-grid large"><button v-for="b in visibleBodies" :key="b.id" class="body-card" :class="{selected:selectedBody===b.id}" @click="selectBody(b.id)"><div class="product-visual"><img v-if="b.image_url" :src="b.image_url"><span v-else>⌁</span></div><div class="card-copy"><strong>{{b.name}}</strong><small>{{b.model}}</small><p>{{b.description}}</p></div><span class="check">{{selectedBody===b.id?'✓':'○'}}</span></button></div><div v-else class="empty-state">没有匹配的花洒主体，请换一个名称或型号。</div></div>
<div v-else-if="employeeStep===2" class="step-panel"><div class="panel-heading"><div><p class="eyebrow">STEP 02 · COMPONENTS</p><h2>选择配件并调整数量</h2><p>先选配件类型，再从右侧挑选对应参数构成的子配件。</p></div><span class="counter">{{selectedLines.length}} 项已选</span></div><div class="accessory-toolbar"><label class="quick-filter"><span>⌕</span><input v-model="query" placeholder="快速筛选配件、型号或参数"><button v-if="query" type="button" aria-label="清除筛选" @click="query=''">×</button></label><span class="result-count">{{visibleAccessories.length}} 个结果</span></div><div class="selected-body-strip"><span>当前主体</span><b>{{activeBody?.name}}</b><button class="secondary change-body-button" @click="employeeStep=1">更换主体</button></div><div class="accessory-browser"><aside class="category-rail"><div class="category-rail-heading"><span>配件类型</span><small>选择一栏</small></div><button v-for="c in categories" :key="c" class="category-item" :class="{active:categoryFilter===c}" @click="categoryFilter=c"><span class="category-marker">{{categoryFilter===c?'●':'○'}}</span><span>{{c}}</span><b>{{c==='全部'?accessories.length:accessories.filter(a=>a.category===c).length}}</b></button></aside><div class="accessory-results"><div class="results-heading"><div><span class="eyebrow">{{categoryFilter==='全部'?'ALL COMPONENTS':categoryFilter.toUpperCase()}}</span><h3>{{categoryFilter==='全部'?'全部配件':categoryFilter}}</h3></div><span class="results-hint">点击卡片选择，右侧调整数量</span></div><div v-if="visibleAccessories.length" class="accessory-grid"><article v-for="a in visibleAccessories" :key="a.id" class="accessory-card" :class="{chosen:!!selected[a.id]}" @click="toggle(a)"><div class="accessory-visual"><img v-if="a.image_url" :src="a.image_url"><span v-else>✧</span></div><div class="accessory-info"><div class="accessory-title"><strong>{{a.name}}</strong></div><small>{{a.model}} · {{a.category}}</small><div class="attribute-row"><span v-for="(v,k) in a.attributes" :key="k">{{k}}：{{formatAttribute(a.category,k,v)}}</span></div></div><div class="quantity" @click.stop><button @click="qty(a,(selected[a.id]||0)-1)">−</button><input type="number" :value="selected[a.id]||0" @input="qty(a,Number(($event.target as HTMLInputElement).value))"><button @click="qty(a,(selected[a.id]||0)+1)">+</button></div></article></div><div v-else class="empty-state">没有匹配的配件。试试其他关键词或切换配件类型。</div></div></div></div>
<div v-else class="step-panel"><div class="panel-heading"><div><p class="eyebrow">STEP 03 · REVIEW</p><h2>确认这套花洒组合</h2><p>检查主体、配件和数量，再计算最终对外售价。</p></div><button class="review-back-button" @click="employeeStep=2">返回调整</button></div><div class="review-list"><div class="review-item main"><div class="mini-visual"><img v-if="activeBody?.image_url" :src="activeBody.image_url" :alt="activeBody.name"><span v-else>⌁</span></div><div><b>{{activeBody?.name}}</b><small>{{activeBody?.model}} · 主体</small></div><strong>1 套</strong></div><div v-for="item in selectedRows" :key="item.id" class="review-item"><div class="mini-visual"><img v-if="item.image_url" :src="item.image_url" :alt="item.name"><span v-else>✧</span></div><div><b>{{item.name}}</b><small>{{item.category}} · {{item.model}}</small></div><strong>× {{item.quantity}}</strong></div><div v-if="!selectedRows.length" class="empty-state">至少选择一个配件后，才能查看套装价格。</div></div><div class="discount-row"><label>折扣方式<FancySelect v-model="discountType" :options="[{label:'百分比折扣',value:'percent'},{label:'固定金额',value:'amount'}]" aria-label="折扣方式"/></label><label>{{discountType==='percent'?'折扣（%）':'减免金额'}}<input v-model.number="discountValue" type="number" min="0" :max="discountType==='percent'?100:undefined"></label></div></div></section>
<aside class="quote-rail"><div class="rail-heading"><p class="eyebrow">LIVE QUOTE</p><span class="live-dot">实时</span></div><h3>套装报价卡</h3><div class="star-track"><span v-for="item in [activeBody,...selectedRows]" :key="item?.id||item?.model" class="track-node"></span></div><div class="rail-composition"><div v-if="activeBody" class="rail-line"><span class="rail-icon">⌁</span><div><b>{{activeBody.name}}</b><small>主体</small></div><em>1</em></div><div v-for="item in selectedRows" :key="item.id" class="rail-line"><span class="rail-icon">✧</span><div><b>{{item.name}}</b><small>{{item.category}}</small></div><em>{{item.quantity}}</em></div><div v-if="!activeBody" class="empty-summary">先从左侧选择主体。</div></div><div v-if="employeeStep===2" class="rail-cta"><button class="primary wide" :disabled="!selectedLines.length" @click="goToStep(3)">进入套装确认 <span>→</span></button><small v-if="!selectedLines.length">至少选择一个配件后继续</small></div><div v-else-if="employeeStep===3" class="rail-cta"><button class="primary wide" :disabled="busy||!selectedLines.length" @click="calculate(false)">{{busy?'计算中…':'计算最终售价'}} <span>→</span></button></div><div class="rail-price"><span>最终对外售价</span><strong v-if="preview&&selectedLines.length">¥ {{preview.final_price}}</strong><strong v-else class="placeholder-price">{{selectedLines.length?'点击计算查看':'选择配件后显示'}}</strong><small>含税 · 含运费 · 已应用折扣</small></div><button class="secondary wide" :disabled="busy||!preview||!selectedLines.length" @click="calculate(true)">保存报价单</button><p v-if="notice" class="notice">{{notice}}</p><div class="quote-history"><div class="history-head"><span>最近报价</span><button class="text-button" @click="loadQuotes">刷新</button></div><div v-for="q in quotes.slice(0,5)" :key="q.quote_no" class="history-row"><button class="history-link" @click="openQuote(q.quote_no)"><b>{{q.quote_no}}</b><small>{{date(q.created_at)}} · {{statusText(q.status)}}{{q.status!=='expired'?'至 '+date(q.valid_until):''}}</small></button><strong>¥ {{q.final_price}}</strong></div><div v-if="!quotes.length" class="empty-summary">还没有保存过报价。</div></div><div v-if="quoteDetail" class="detail-card"><div><b>{{quoteDetail.quote_no}}</b><span>{{statusText(quoteDetail.status)}}</span></div><small>有效至 {{date(quoteDetail.valid_until)}}</small><button class="text-button" @click="duplicateQuote(quoteDetail.quote_no)">复制为新报价</button></div></aside></div></section>
<section v-else class="admin-shell"><aside class="admin-sidebar"><div class="admin-sidebar-title"><span class="admin-orbit">✦</span><div><b>控制室</b><small>ADMIN CONTROL ROOM</small></div></div><p class="sidebar-caption">维护产品、规则与价格<br>员工端只看到最终售价。</p><nav><button v-for="tab in ['概览','计价参数','主体','配件','规则','账号','报价','日志']" :key="tab" :class="{active:adminTab===tab}" @click="adminTab=tab;clearForms()"><span>{{{'概览':'⌂','计价参数':'◒','主体':'◇','配件':'✧','规则':'⇄','账号':'◎','报价':'▣','日志':'☷'}[tab]}}</span>{{tab}}</button></nav></aside><div class="admin-main"><div class="admin-mobile-head"><div><p class="eyebrow">CONTROL ROOM</p><h1>价格规则，由你掌舵。</h1></div><button class="ghost" @click="logout">退出</button></div>
<section v-if="adminTab==='概览'" class="admin-page"><div class="page-heading"><div><p class="eyebrow">OVERVIEW</p><h2>今天的维护工作台</h2><p>从这里查看数据状态，或直接进入对应模块维护。</p></div><button class="primary" @click="adminTab='配件';startAccessoryCreate()">＋ 新增配件</button></div><div class="metric-grid"><div><span>启用主体</span><strong>{{activeBodyCount}}</strong><small>共 {{adminBodies.length}} 条</small></div><div><span>启用配件</span><strong>{{activeAccessoryCount}}</strong><small>共 {{adminAccessories.length}} 条</small></div><div><span>有效报价</span><strong>{{activeQuoteCount}}</strong><small>全部 {{adminQuotes.length}} 张</small></div><div><span>启用账号</span><strong>{{activeUserCount}}</strong><small>共 {{users.length}} 个</small></div></div><div class="overview-analytics"><article class="admin-card analytics-card trend-card"><div class="analytics-head"><div><p class="eyebrow">QUOTE PULSE</p><h3>报价趋势</h3><span>观察报价单在不同周期的变化</span></div><div class="chart-switch"><button :class="{active:quoteChartMode==='week'}" @click="quoteChartMode='week'">近7天</button><button :class="{active:quoteChartMode==='month'}" @click="quoteChartMode='month'">近6个月</button></div></div><div class="analytics-total"><strong>{{quoteTrend.totalCount}}</strong><span>张报价 · 周期合计 ¥ {{quoteTrend.totalAmount.toFixed(0)}}</span></div><div ref="quoteChartEl" class="trend-chart" role="img" aria-label="报价数量渐变折线图"></div></article><article class="admin-card analytics-card status-card"><div class="analytics-head"><div><p class="eyebrow">QUOTE MIX</p><h3>报价状态</h3><span>快速查看报价所处阶段</span></div></div><div class="status-total"><strong>{{adminQuotes.length}}</strong><span>全部报价单</span></div><div v-for="item in quoteStatusBreakdown" :key="item.key" class="status-bar-row"><div class="status-row-label"><span><i :style="{background:item.color}"></i>{{item.label}}</span><b>{{item.value}}</b></div><div class="status-bar"><span :style="{width:(item.value/(adminQuotes.length||1)*100)+'%',background:item.color}"></span></div></div><div v-if="!adminQuotes.length" class="empty-state">暂无报价记录，数据出现后会在这里形成分布。</div></article></div><div class="overview-grid"><div class="admin-card focus-card"><p class="eyebrow">PRODUCT MODEL</p><h3>主体 → 配件 → 套装报价</h3><p>员工每次只选择一个主体，再按照客户需求添加配件和数量。系统保留保存时的完整价格快照。</p><button class="text-button" @click="adminTab='主体'">维护主体目录 →</button></div><div class="admin-card quick-list"><div class="card-title"><div><p class="eyebrow">RECENT QUOTES</p><h3>最近报价</h3></div><button class="text-button" @click="adminTab='报价'">查看全部</button></div><div v-for="x in adminQuotes.slice(0,4)" :key="x.quote_no" class="table-row compact"><span><b>{{x.quote_no}}</b><small>{{x.username}} · {{date(x.created_at)}}</small></span><strong>¥ {{x.final_price}}</strong></div></div></div></section>
<section v-else-if="adminTab==='计价参数'" class="admin-page"><div class="page-heading"><div><p class="eyebrow">PRICING SETTINGS</p><h2>统一计价参数</h2><p>这些参数会被所有新报价使用，历史报价不受影响。</p></div><div class="pricing-heading-actions"><button type="button" class="secondary" :class="{'is-open':pricingGuideOpen}" @click="pricingGuideOpen=!pricingGuideOpen">{{pricingGuideOpen?'收起计算规则':'计算规则'}}</button><button class="primary" @click="saveSettings">保存变更</button></div></div><div class="admin-card settings-card"><div class="settings-grid"><label>统一倍率<input v-model="settings.multiplier" type="number" min="1" step="0.01"></label><label>统一人工费<input v-model="settings.labor_fee" type="number" step="0.01"></label><label>税率（%）<input v-model="settings.tax_rate_percent" type="number" step="0.01"></label><label>每张报价运费<input v-model="settings.freight" type="number" step="0.01"></label><label>默认有效期（天）<input v-model="settings.quote_valid_days" type="number" min="1"></label><label>最大折扣（%）<input v-model="settings.max_discount_percent" type="number" step="0.01"></label><label>最低售价<input v-model="settings.minimum_price" type="number" step="0.01"></label></div><div class="formula-note"><span>计价顺序</span><b>成本小计 × 倍率 → 折扣 → 税费 → 运费 → 最终售价</b></div></div><div v-if="pricingGuideOpen" class="modal-backdrop pricing-guide-backdrop" @click.self="pricingGuideOpen=false"><div class="pricing-guide pricing-guide-modal admin-card"><div class="pricing-guide-head"><div><h3>计算规则流程</h3><span>从校验到最终售价，按箭头顺序执行</span></div><button type="button" class="pill-button" @click="pricingGuideOpen=false">关闭</button></div><div class="pricing-flow" aria-label="报价计算流程"><div class="pricing-flow-row pricing-flow-row-top"><div class="pricing-flow-node is-check"><span class="pricing-flow-index">01 · 先检查</span><strong>主体、配件与兼容性</strong><small>主体和配件必须启用；数量须在最小/最大值内。互斥不能同时选，依赖必须补齐。</small></div><span class="pricing-flow-arrow">→</span><div class="pricing-flow-node"><span class="pricing-flow-index">02 · 汇总成本</span><strong>成本小计</strong><small>主体成本 + Σ（配件成本 × 数量）+ 统一人工费。</small></div><span class="pricing-flow-arrow">→</span><div class="pricing-flow-node"><span class="pricing-flow-index">03 · 放大成本</span><strong>统一倍率</strong><small>计价基数 = 成本小计 × 倍率；倍率最低为 1。</small></div></div><div class="pricing-flow-turn"><span>↓</span><small>进入价格调整</small></div><div class="pricing-flow-row pricing-flow-row-bottom"><div class="pricing-flow-node is-result"><span class="pricing-flow-index">06 · 输出结果</span><strong>最终售价</strong><small>折扣后金额 + 税费 + 运费，保留两位小数；低于最低售价则拒绝报价。</small></div><span class="pricing-flow-arrow">←</span><div class="pricing-flow-node"><span class="pricing-flow-index">05 · 加上税费</span><strong>税费</strong><small>税费 = 折扣后金额 × 税率。</small></div><span class="pricing-flow-arrow">←</span><div class="pricing-flow-node"><span class="pricing-flow-index">04 · 先减折扣</span><strong>折扣</strong><small>百分比或固定金额均受“计价基数 × 最大折扣比例”限制，折扣后不低于 0。</small></div></div><div class="pricing-flow-notes"><span><b>有效期</b> 只决定到期日期，不参与金额计算</span><span><b>历史报价</b> 保存创建时的价格快照，不随参数修改</span><span><b>清空字段</b> 金额/比例按 0；倍率按 1；有效期按 15 天</span></div><div class="pricing-flow-example"><b>例：</b>成本小计 1,000 元 × 倍率 1.5 = 计价基数 1,500 元；最大折扣 20% 时，最多减免 300 元，再计算税费并加运费。</div></div></div></div></section>
<section v-else-if="adminTab==='主体'" class="admin-page"><div class="page-heading"><div><p class="eyebrow">PRODUCT BODIES</p><h2>主体目录</h2><p>花洒主体是每张报价的起点，可维护图片、型号、描述和成本。</p></div><button class="primary" @click="editing='body'">＋ 新增主体</button></div><div v-if="editing==='body'" class="modal-backdrop" @click.self="clearForms"><div class="accessory-modal body-modal" role="dialog" aria-modal="true"><div class="modal-intro"><span class="eyebrow">BODY EDITOR</span><p>维护主体名称、型号、成本和描述，保存后立即生效。</p></div><form class="admin-card edit-form" @submit.prevent="saveBody"><div class="form-title"><b>{{bodyForm.id?'编辑主体':'新增主体'}}</b><button type="button" class="text-button" @click="clearForms">取消</button></div><div class="form-grid"><label>名称<input v-model="bodyForm.name" placeholder="例如：星瀑花洒主体" required></label><label>型号<input v-model="bodyForm.model" placeholder="SH-001" required></label><label>成本<div class="unit-input"><input v-model="bodyForm.cost" type="number" step="0.01" min="0" required><span>元</span></div></label><label>图片<span class="file-input"><input type="file" accept="image/jpeg,image/png,image/webp" @change="uploadImage($event,'body')"><span class="file-button">选择文件</span><span class="file-name">{{bodyForm.image_url?'已选择文件':'未选择任何文件'}}</span></span><small v-if="bodyForm.image_url" class="file-ready">已选择图片</small></label><label class="span-2">描述<textarea v-model="bodyForm.description" rows="3" placeholder="材质、适用场景、组合说明"></textarea></label><label class="check-label"><input v-model="bodyForm.active" type="checkbox">启用</label></div><button class="primary">保存主体</button></form></div></div><div class="admin-card data-card"><div v-if="!adminBodies.length" class="empty-state">还没有主体，请先新增一条。</div><div v-for="x in adminBodies" :key="x.id" class="data-row body-data-row"><div class="data-thumb"><img v-if="x.image_url" :src="x.image_url"><span v-else>⌁</span></div><div class="data-main"><b>{{x.name}}</b><small>{{x.model}} · v{{x.version}} · {{x.description||'暂无描述'}}</small></div><strong class="cost">{{money(x.cost)}}</strong><div class="resource-row-actions"><button type="button" class="pill-button status-action" :class="{'is-active':x.active}" :disabled="x.active" @click="setBodyActive(x,true)">启用</button><button type="button" class="pill-button status-action" :class="{'is-off':!x.active}" :disabled="!x.active" @click="setBodyActive(x,false)">停用</button><button type="button" class="pill-button" @click="editBody(x)">编辑</button><button type="button" class="pill-button pill-danger" @click="softDelete('body',x.id)" :disabled="!x.active">删除</button></div></div></div></section>
<section v-else-if="adminTab==='配件'" class="admin-page"><div class="page-heading"><div><p class="eyebrow">ACCESSORY LIBRARY</p><h2>配件目录</h2><p>按类别录入截图中的结构化字段，员工端会自动显示这些参数。</p></div><button class="primary" @click="startAccessoryCreate()">＋ 新增配件</button></div><div class="admin-accessory-browser"><aside class="admin-category-rail" @wheel="forwardAccessoryWheel"><div class="admin-category-rail-heading"><span>配件类型</span><small>按类型维护</small></div><button v-for="c in adminAccessoryCategories" :key="c" class="admin-category-item" :class="{active:adminAccessoryCategoryFilter===c}" @click="adminAccessoryCategoryFilter=c"><span class="admin-category-dot">{{adminAccessoryCategoryFilter===c?'●':'○'}}</span><span>{{c}}</span><b>{{c==='全部'?adminAccessories.length:adminAccessories.filter(x=>x.category===c).length}}</b></button></aside><div class="admin-accessory-results"><div class="admin-card data-card"><div v-if="!visibleAdminAccessories.length" class="empty-state">还没有配件，请先新增一条。</div><div v-for="x in visibleAdminAccessories" :key="x.id" class="data-row accessory-admin-row"><div class="data-thumb"><img v-if="x.image_url" :src="x.image_url"><span v-else>✧</span></div><div class="data-main"><b>{{x.name}}</b><small>{{x.model}} · {{x.category}} · 数量 {{x.min_qty}}–{{x.max_qty}}</small><div class="attribute-row"><span v-for="(v,k) in x.attributes" :key="k">{{k}}：{{formatAttribute(x.category,k,v)}}</span></div></div><strong class="cost">¥ {{x.cost}}</strong><div class="accessory-row-actions"><button type="button" class="pill-button status-action" :class="{'is-active':x.active}" :disabled="x.active" @click="setAccessoryActive(x,true)">启用</button><button type="button" class="pill-button status-action" :class="{'is-off':!x.active}" :disabled="!x.active" @click="setAccessoryActive(x,false)">停用</button><button type="button" class="pill-button" @click="editAccessory(x)">编辑</button><button type="button" class="pill-button pill-danger" @click="deleteAccessory(x)">删除</button></div></div></div></div></div><div v-if="editing==='accessory'" class="modal-backdrop" @click.self="clearForms"><div class="accessory-modal" role="dialog" aria-modal="true"><div class="modal-intro"><span class="eyebrow">ACCESSORY EDITOR</span><p>填写配件信息，保存后会回到当前分类列表。</p></div><form class="admin-card edit-form" @submit.prevent="saveAccessory"><div class="form-title"><b>{{accessoryForm.id?'编辑配件':'新增配件'}}</b><button type="button" class="pill-button modal-cancel" @click="clearForms">取消</button></div><div class="form-grid"><label>名称<input v-model="accessoryForm.name" required></label><label>型号<input v-model="accessoryForm.model" required></label><label>类别<FancySelect v-model="accessoryForm.category" :options="accessoryCategoryOptions.map(c=>({label:c,value:c}))" aria-label="类别"/></label><label>成本<div class="unit-input"><input v-model="accessoryForm.cost" type="number" inputmode="decimal" step="0.01" min="0" required><span>元</span></div></label><label>最大数量<input v-model="accessoryForm.max_qty" type="number" min="0" step="1"></label><label>图片<span class="file-input"><input type="file" accept="image/jpeg,image/png,image/webp" @change="uploadImage($event,'accessory')"><span class="file-button">选择文件</span><span class="file-name">{{accessoryForm.image_url?'已选择文件':'未选择任何文件'}}</span></span><small v-if="accessoryForm.image_url" class="file-ready">已选择图片</small></label><div v-if="selectedAccessorySchema?.note" class="schema-note span-2">{{selectedAccessorySchema.note}}</div><label v-for="f in selectedAccessorySchema?.fields||[]" :key="f.key">{{f.label}}<FancySelect v-if="f.type==='select'" :model-value="accessoryForm.attributes[f.key]||''" :options="(f.options||[]).map(option=>({label:option,value:option}))" :aria-label="f.label" @update:model-value="setAccessoryAttribute(f.key,String($event))"/><div v-else-if="f.unit" class="unit-input"><input type="text" inputmode="decimal" :value="numericOnly(accessoryForm.attributes[f.key]||'')" :placeholder="f.label" @input="setAccessoryAttribute(f.key,numericOnly(($event.target as HTMLInputElement).value))"><span>{{f.unit}}</span></div><input v-else :value="accessoryForm.attributes[f.key]||''" :placeholder="f.label" @input="setAccessoryAttribute(f.key,($event.target as HTMLInputElement).value)"></label></div><div class="form-actions"><span></span><button class="primary">保存配件</button></div></form></div></div></section>
<section v-else-if="adminTab==='规则'" class="admin-page"><div class="page-heading"><div><p class="eyebrow">COMPATIBILITY</p><h2>兼容规则</h2><p>用依赖和互斥规则避免员工组合出无法生产的套装。</p></div></div><div class="rule-builder admin-card"><div class="rule-builder-head"><div><p class="eyebrow">RULE BUILDER</p><h3>新增一条组合规则</h3><p>先选择规则类型，再指定源配件和目标配件。</p></div><span class="rule-builder-hint">规则只参与组合校验，不改变价格</span></div><form class="rule-form" @submit.prevent="saveRule"><label class="rule-field"><span>规则类型</span><FancySelect v-model="ruleForm.rule_type" :options="[{label:'互斥',value:'excludes'},{label:'依赖',value:'requires'}]" aria-label="规则类型"/></label><label class="rule-field"><span>源配件 <small>先被选择的配件</small></span><FancySelect v-model="ruleForm.source_accessory_id" :options="[{label:'请选择源配件',value:0},...adminAccessories.map(x=>({label:x.name,value:x.id}))]" aria-label="源配件"/></label><div class="rule-connector"><span class="rule-connector-line"></span><b>{{ruleForm.rule_type==='excludes'?'不能同时选择':'必须同时选择'}}</b><span class="rule-connector-line"></span></div><label class="rule-field"><span>目标配件 <small>与源配件的关系对象</small></span><FancySelect v-model="ruleForm.target_accessory_id" :options="[{label:'请选择目标配件',value:0},...adminAccessories.map(x=>({label:x.name,value:x.id}))]" aria-label="目标配件"/></label><button class="primary rule-submit">新增规则</button></form><div class="rule-preview"><span>规则预览</span><strong>{{accessoryName(ruleForm.source_accessory_id)}} {{ruleForm.rule_type==='excludes'?'不能同时选择':'必须同时选择'}} {{accessoryName(ruleForm.target_accessory_id)}}</strong></div></div><div class="rule-list admin-card"><div class="rule-list-head"><div><h3>已配置规则</h3><p>员工组合配件时，系统会按以下规则进行校验。</p></div><span>{{rules.length}} 条规则</span></div><div v-if="!rules.length" class="empty-state">还没有配置规则。</div><div v-for="r in rules" :key="r.id" class="rule-card"><div class="rule-card-type" :class="r.rule_type==='excludes'?'is-excludes':'is-requires'"><strong>{{r.rule_type==='excludes'?'互斥':'依赖'}}</strong><small>{{r.rule_type==='excludes'?'两个配件不能同时选择':'选择源配件时必须选择目标配件'}}</small></div><div class="rule-card-flow"><div class="rule-endpoint"><small>源配件</small><b>{{accessoryName(r.source_accessory_id)}}</b><em>#{{r.source_accessory_id}}</em></div><div class="rule-card-connector"><span>{{r.rule_type==='excludes'?'不能同时':'需要同时'}}</span><i>→</i></div><div class="rule-endpoint"><small>目标配件</small><b>{{accessoryName(r.target_accessory_id)}}</b><em>#{{r.target_accessory_id}}</em></div></div><div class="rule-card-actions"><button type="button" class="pill-button status-action" :class="{'is-active':r.active}" :disabled="r.active" @click="setRuleActive(r,true)">启用</button><button type="button" class="pill-button status-action" :class="{'is-off':!r.active}" :disabled="!r.active" @click="setRuleActive(r,false)">停用</button><button type="button" class="pill-button pill-danger" @click="deleteRule(r)">删除</button></div></div></div></section>
<section v-else-if="adminTab==='账号'" class="admin-page"><div class="page-heading"><div><p class="eyebrow">TEAM ACCESS</p><h2>账号管理</h2><p>不开放注册，管理员逐个创建账号并随时停用。</p></div><button class="primary" @click="editing='user'">＋ 新增账号</button></div><div v-if="editing==='user'" class="modal-backdrop" @click.self="clearForms"><div class="accessory-modal account-modal" role="dialog" aria-modal="true"><div class="modal-intro"><span class="eyebrow">ACCOUNT EDITOR</span><p>修改账号、密码和角色，保存后立即生效。</p></div><form v-if="editing==='user'" class="admin-card edit-form" @submit.prevent="saveUser"><div class="form-title"><b>{{userForm.id?'编辑账号':'新增账号'}}</b><button type="button" class="pill-button modal-cancel" @click="clearForms">取消</button></div><div class="form-grid"><label>账号<input v-model="userForm.username" required></label><label>密码<span class="password-input"><input v-model="userForm.password" :type="showPassword?'text':'password'" :placeholder="userForm.id?'留空表示不修改':'至少 8 位'" :required="!userForm.id"><button type="button" class="password-toggle" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></span><small>{{userForm.id?'编辑账号时可留空，保留原密码；输入新密码即可替换。':'新增账号直接设置密码即可，无需输入原始密码。'}}</small></label><label>角色<FancySelect v-model="userForm.role" :options="[{label:'员工',value:'employee'},{label:'管理员',value:'admin'}]" aria-label="角色"/></label></div><div class="form-actions"><span></span><button class="primary">保存账号</button></div></form></div></div><div class="admin-card data-card"><div v-for="x in users" :key="x.id" class="data-row account-data-row"><div class="avatar">{{x.username.slice(0,1).toUpperCase()}}</div><div class="data-main"><b>{{x.username}}</b><small>{{x.role==='admin'?'管理员':'员工'}} · 最后登录 {{x.last_login?date(x.last_login):'暂无'}}</small></div><div class="resource-row-actions"><button type="button" class="pill-button status-action" :class="{'is-active':x.active}" :disabled="x.active" @click="setUserActive(x,true)">启用</button><button type="button" class="pill-button status-action" :class="{'is-off':!x.active}" :disabled="!x.active" @click="setUserActive(x,false)">停用</button><button type="button" class="pill-button" @click="editUser(x)">编辑</button><button type="button" class="pill-button pill-danger" @click="softDelete('user',x.id)" :disabled="!x.active||x.username===session?.username">删除</button></div></div></div></section>
<section v-else-if="adminTab==='报价'" class="admin-page"><div class="page-heading"><div><p class="eyebrow">ALL QUOTES</p><h2>报价记录</h2><p>查看员工报价、有效期和保存时的价格版本。</p></div><button type="button" class="pill-button refresh-button" @click="loadAdmin">刷新</button></div><div class="admin-card data-card"><div v-for="x in adminQuotes" :key="x.quote_no" class="data-row quote-data-row" :class="{isVoid:x.status==='void'}"><div class="quote-code">▣</div><div class="data-main"><b>{{x.quote_no}}</b><small>{{x.username}} · {{date(x.created_at)}} · 有效至 {{date(x.valid_until)}}</small></div><strong class="cost">¥ {{x.final_price}}</strong><span class="status-pill">{{statusText(x.status)}}</span><div class="resource-row-actions"><button type="button" class="pill-button" @click="openAdminQuote(x.quote_no)">详情</button><button type="button" class="pill-button status-action is-off" @click="voidQuote(x.quote_no)" :disabled="x.status==='void'">作废</button><button type="button" class="pill-button pill-danger" @click="deleteQuote(x)">删除</button></div></div><div v-if="!adminQuotes.length" class="empty-state">还没有报价记录。</div></div><div v-if="adminQuoteDetail" class="modal-backdrop quote-detail-modal-backdrop" @click.self="adminQuoteDetail=null"><div class="accessory-modal quote-detail-modal" role="dialog" aria-modal="true"><div class="admin-card quote-detail-panel"><div class="form-title"><b>{{adminQuoteDetail.quote_no}} · 完整快照</b><button type="button" class="pill-button" @click="adminQuoteDetail=null">关闭</button></div><div class="snapshot-grid"><div><span>主体</span><b>{{adminQuoteDetail.body?.name}}</b></div><div><span>最终售价</span><b>¥ {{adminQuoteDetail.final_price}}</b></div><div><span>主体成本</span><b>¥ {{adminQuoteDetail.private?.body_cost}}</b></div><div><span>成本小计</span><b>¥ {{adminQuoteDetail.private?.subtotal}}</b></div><div><span>倍率</span><b>{{adminQuoteDetail.private?.multiplier}}</b></div><div><span>人工费</span><b>¥ {{adminQuoteDetail.private?.labor_fee}}</b></div><div><span>税费</span><b>¥ {{adminQuoteDetail.private?.tax}}</b></div><div><span>运费</span><b>¥ {{adminQuoteDetail.private?.freight}}</b></div></div></div><div class="snapshot-lines"><b>配件快照</b><div v-for="line in adminQuoteDetail.lines||[]" :key="line.accessory_id" class="snapshot-line"><span>{{line.name||line.accessory_name||('配件 #'+line.accessory_id)}} × {{line.quantity}}</span><strong>¥ {{line.line_total||line.unit_price||'0.00'}}</strong></div></div></div></div></section>
<section v-else class="admin-page"><div class="page-heading"><div><p class="eyebrow">AUDIT TRAIL</p><h2>操作日志</h2><p>管理员的新增、修改、启停、删除、作废、上传和试算操作都会留下记录。</p></div><div class="log-page-actions"><button type="button" class="pill-button refresh-button" @click="loadAdmin">刷新</button><button type="button" class="pill-button pill-danger" @click="clearLogs">清除日志</button></div></div><div class="admin-card data-card"><div v-for="x in logs" :key="x.id" class="data-row log-data-row"><div class="log-icon">☷</div><div class="data-main"><b>{{formatLogAction(x.action)}} · {{formatLogTarget(x.target_type)}}</b><small>{{x.username||'系统'}} · {{dateTime(x.created_at)}} · {{logTargetRef(x) || '—'}}</small></div><div class="log-detail"><span class="log-detail-preview">{{formatLogDetail(x.detail)}}</span><button type="button" class="pill-button" @click="selectedLog=x">查看详情</button></div></div></div><div v-if="selectedLog" class="modal-backdrop log-detail-modal-backdrop" @click.self="selectedLog=null"><div class="accessory-modal log-detail-modal" role="dialog" aria-modal="true"><div class="form-title"><b>{{formatLogAction(selectedLog.action)}} · {{formatLogTarget(selectedLog.target_type)}}</b><button type="button" class="pill-button" @click="selectedLog=null">关闭</button></div><div class="log-modal-meta"><span>操作者：{{selectedLog.username||'系统'}}</span><span>时间：{{dateTime(selectedLog.created_at)}}</span><span>对象：{{logTargetRef(selectedLog)||'—'}}</span></div><div class="log-detail-list"><div v-for="entry in logDetailEntries(selectedLog.detail)" :key="entry.key" class="log-detail-item"><b>{{entry.key}}</b><span>{{entry.value}}</span></div></div></div></div></section>
</div></section></section>
</main>
</template>
